    const db = getDb();

    db.get(
      `SELECT u.id, u.email, u.name, u.initials, u.highest_level, u.best_score
       FROM tokens t
       JOIN users u ON t.user_id = u.id
       WHERE t.token = ?`,
      [token],
      (err, row) => {
        db.close();
        if (err) {
          reject(err);
        } else {
          resolve(row || null);
        }
      }
    );
  });
}

function signOut(token) {
  return new Promise((resolve, reject) => {
    const db = getDb();

    db.run(
      "DELETE FROM tokens WHERE token = ?",
      [token],
      (err) => {
        db.close();
        if (err) {
          reject(err);
        } else {
          resolve();
        }
      }
    );
  });
}

