  GameState,
  STATES,
  CANVAS_WIDTH,
  CANVAS_HEIGHT,
  BRICK_WIDTH,
  BRICK_HEIGHT,
  BRICK_PADDING,
  PADDLE_HEIGHT,
  BALL_RADIUS
};
