    .level-select {
      background: rgba(0, 0, 0, 0.3);
      border: 1px solid #f39c12;
      border-radius: 8px;
      padding: 15px;
      margin-bottom: 15px;
    }

    .level-select h3 {
      margin-bottom: 10px;
      font-size: 16px;
    }

    .level-buttons {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(80px, 1fr));
      gap: 8px;
    }

    .level-btn {
      padding: 10px;
      border: 2px solid #f39c12;
      background: rgba(0, 0, 0, 0.3);
      color: #fff;
      border-radius: 6px;
      cursor: pointer;
      font-weight: 600;
      transition: all 0.2s;
      font-size: 13px;
