<body>
  <div class="container">
    <div class="header">
      <h1>🧱 BRICKFALL</h1>
      <div class="header-right">
        <div class="user-info" id="userInfo" style="display: none;">
          <strong id="userEmail"></strong>
          <span id="userName"></span>
        </div>
        <button class="btn btn-secondary" id="signInBtn" onclick="showSignIn()">Sign In</button>
        <button class="btn btn-danger" id="signOutBtn" onclick="signOut()" style="display: none;">Sign Out</button>
      </div>
    </div>

    <div class="main-content">
      <!-- Sign In Section -->
      <div id="signInSection" class="sign-in-form">
        <h2 style="margin-bottom: 20px; text-align: center;">Sign In</h2>
        <div class="form-group">
          <label for="emailInput">Email</label>
          <input type="email" id="emailInput" placeholder="mira@brickfall.test">
        </div>
        <div class="form-group">
          <label for="passwordInput">Password</label>
          <input type="password" id="passwordInput" placeholder="password123">
        </div>
        <button class="btn btn-primary" onclick="handleSignIn()" style="width: 100%; margin-top: 10px;">Sign In</button>
        <div style="text-align: center; margin-top: 15px; font-size: 12px; opacity: 0.7;">
          Demo accounts: mira@brickfall.test, dev@brickfall.test, polly@brickfall.test<br>
          Password: password123
        </div>
      </div>

      <!-- Game Section -->
      <div id="gameSection" class="game-section" style="display: none;">
        <div id="statusMessage" class="status-message" style="display: none;"></div>

        <!-- Level Select -->
        <div id="levelSelect" class="level-select" style="display: none;">
          <h3>Select Level</h3>
          <div class="level-buttons" id="levelButtons"></div>
        </div>

        <!-- Canvas -->
        <div class="canvas-wrapper">
          <canvas id="gameCanvas" width="900" height="600" role="img" aria-label="Game canvas"></canvas>
        </div>

        <!-- HUD -->
        <div class="hud">
          <div class="hud-item">
            <div class="hud-label">Score</div>
            <div class="hud-value" id="scoreDisplay">0</div>
          </div>
          <div class="hud-item">
            <div class="hud-label">Lives</div>
            <div class="hud-value" id="livesDisplay">3</div>
          </div>
          <div class="hud-item">
            <div class="hud-label">Level</div>
            <div class="hud-value" id="levelDisplay">1</div>
          </div>
          <div class="hud-item">
            <div class="hud-label">Combo</div>
            <div class="hud-value" id="comboDisplay">x1</div>
          </div>
          <div class="hud-item">
            <div class="hud-label">Power-Up</div>
            <div class="hud-value" id="powerDisplay">—</div>
          </div>
          <div class="hud-item">
            <div class="hud-label">Revision</div>
            <div class="hud-value" id="revisionDisplay">—</div>
          </div>
        </div>

        <!-- Controls -->
        <div class="controls">
          <div class="control-group">
            <button class="btn btn-primary" id="launchBtn" onclick="launchBall()" style="display: none;">Launch (Space)</button>
            <button class="btn btn-secondary" id="pauseBtn" onclick="togglePause()">Pause (P)</button>
            <button class="btn btn-danger" id="restartBtn" onclick="restartGame()" style="display: none;">Restart (R)</button>
          </div>
          <div class="assist-toggle" id="assistToggle">
            <input type="checkbox" id="assistCheckbox" onchange="toggleAssist()">
            <label for="assistCheckbox" style="margin: 0; cursor: pointer;">Assist Paddle</label>
          </div>
        </div>

        <!-- Events Log -->
        <div class="events-log" id="eventsLog"></div>

        <!-- Leaderboard -->
        <div class="leaderboard">
          <h3>Top 10 Leaderboard</h3>
          <table class="leaderboard-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Player</th>
                <th>Score</th>
                <th>Level</th>
              </tr>
            </thead>
            <tbody id="leaderboardBody">
            </tbody>
          </table>
        </div>
      </div>
    </div>
  </div>

  <!-- Modal -->
  <div id="modal" class="modal">
    <div class="modal-content">
      <h2 id="modalTitle"></h2>
      <div id="modalBody"></div>
      <div class="modal-buttons">
        <button class="btn btn-secondary" onclick="closeModal()">Close</button>
      </div>
    </div>
  </div>

  <script src="game.js"></script>
</body>
</html>
