  // Update game state
  gameState.simulation_time += deltaTime;

  // Clamp accumulator
  let accumulator = 0;
  const PHYSICS_STEP = 1 / 120;

  while (accumulator < deltaTime && gameState.state !== 'paused' && gameState.state !== 'ready') {
    simulationStep();
    accumulator += PHYSICS_STEP;
