function launchBall() {
  if (!gameState) return;

  if (gameState.state === 'ready') {
    gameState.state = 'playing';
    gameState.balls.forEach(b => {
      b.stuck = false;
    });
  } else if (gameState.state === 'life-lost') {
    gameState.state = 'ready';
    gameState.balls = [{
      id: 'primary',
      x: paddleX + gameState.paddle_width / 2,
      y: CANVAS_HEIGHT - 60,
      vx: 0,
      vy: -constants.base_speed,
      stuck: true
    }];
  } else if (gameState.state === 'level-complete') {
    startNewRun(gameState.level + 1);
  } else if (gameState.state === 'game-over') {
    restartGame();
  }
}

function togglePause() {
  if (!gameState) return;

  if (gameState.state === 'playing') {
