      finishRun('completed');
    } else {
      startNewRun(gameState.level + 1);
    }
  } else if (gameState.state === 'game-over') {
    finishRun('game-over');
  }
}

function togglePause() {
  if (!gameState) return;
  if (gameState.state === 'playing') {
    gameState.state = 'paused';
  } else if (gameState.state === 'paused') {
    gameState.state = 'playing';
  }
}

function restartGame() {
  if (!gameState) return;
  showLevelSelect();
}

function movePaddle(x) {
  if (!gameState) return;
  paddleX = Math.max(0, Math.min(x, CANVAS_WIDTH - gameState.paddle_width));
}

function toggleAssist() {
  // Assist paddle toggle
}

function showSignIn() {
  document.getElementById('signInSection').style.display = 'block';
  document.getElementById('gameSection').style.display = 'none';
}

function signOut() {
  fetch('/api/signout', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${token}` }
  }).then(() => {
    token = null;
    localStorage.removeItem('brickfall_token');
    currentUser = null;
    gameState = null;
    showSignIn();
  });
}

async function finishRun(outcome) {
  try {
    const response = await fetch('/api/run/finish', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        runId,
        revision,
        operationId: Math.random().toString(36).substr(2, 9),
        snapshot: gameState,
        outcome
      })
    });
    if (response.ok) {
      const data = await response.json();
      showStatus(`Run finished! Score: ${gameState.score}`, 'success');
      await loadLeaderboard();
      showLevelSelect();
    }
  } catch (err) {
    console.error('Finish run error:', err);
    showStatus('Failed to finish run', 'error');
  }
}

async function loadLeaderboard() {
  try {
    const response = await fetch('/api/leaderboard');
    const data = await response.json();
    const tbody = document.getElementById('leaderboardBody');
    tbody.innerHTML = '';
    data.leaderboard.forEach((entry, index) => {
      const row = document.createElement('tr');
      row.innerHTML = `<td>${index + 1}</td><td>${entry.initials}</td><td>${entry.score}</td><td>${entry.level}</td>`;
      tbody.appendChild(row);
    });
  } catch (err) {
    console.error('Leaderboard load error:', err);
  }
}

function showStatus(message, type = 'success') {
  const statusEl = document.getElementById('statusMessage');
  statusEl.textContent = message;
  statusEl.className = `status-message ${type}`;
  statusEl.style.display = 'block';
  setTimeout(() => {
    statusEl.style.display = 'none';
  }, 5000);
}

function closeModal() {
  document.getElementById('modal').classList.remove('active');
}

function checkCircleRectCollision(cx, cy, cr, rx, ry, rw, rh) {
  const closestX = Math.max(rx, Math.min(cx, rx + rw));
  const closestY = Math.max(ry, Math.min(cy, ry + rh));
  const dx = cx - closestX;
  const dy = cy - closestY;
  return (dx * dx + dy * dy) < (cr * cr);
}

function getCollisionNormal(cx, cy, cr, rx, ry, rw, rh) {
  const closestX = Math.max(rx, Math.min(cx, rx + rw));
  const closestY = Math.max(ry, Math.min(cy, ry + rh));
  const dx = cx - closestX;
  const dy = cy - closestY;
  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
  return {
    point: { x: closestX + (dx / dist) * cr, y: closestY + (dy / dist) * cr },
    normal: { x: dx / dist, y: dy / dist }
  };
}

function reflectVelocity(vx, vy, nx, ny) {
  const dot = vx * nx + vy * ny;
  return {
    x: vx - 2 * dot * nx,
    y: vy - 2 * dot * ny
  };
}
ENDGAME
