// Brickfall Game Client
let token = localStorage.getItem('brickfall_token');
let currentUser = null;
let gameState = null;
let runId = null;
let revision = null;
let canvas = null;
let ctx = null;
let constants = null;
let paddleX = 450;
let lastSaveTime = 0;
const SAVE_INTERVAL = 5000;
const CANVAS_WIDTH = 900;
const CANVAS_HEIGHT = 600;
const PHYSICS_STEP = 1 / 120;
const MIN_VELOCITY = 50;
const BALL_RADIUS = 9;
const PADDLE_HEIGHT = 18;

window.addEventListener('DOMContentLoaded', async () => {
  canvas = document.getElementById('gameCanvas');
  ctx = canvas.getContext('2d');
  try {
    const response = await fetch('/api/constants');
    const data = await response.json();
    constants = data.constants;
  } catch (err) {
    console.error('Failed to load constants:', err);
  }
  if (token) {
    await loadProfile();
  } else {
    showSignIn();
  }
  loadLeaderboard();
  setupEventListeners();
});

function setupEventListeners() {
  document.addEventListener('keydown', (e) => {
    if (e.key === ' ') {
      e.preventDefault();
      launchBall();
    } else if (e.key === 'p' || e.key === 'P') {
      e.preventDefault();
      togglePause();
    } else if (e.key === 'r' || e.key === 'R') {
      e.preventDefault();
      if (gameState && gameState.state === 'game-over') {
        restartGame();
      }
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      movePaddle(paddleX - 20);
    } else if (e.key === 'ArrowRight') {
      e.preventDefault();
      movePaddle(paddleX + 20);
    }
  });
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    paddleX = (e.clientX - rect.left) * scaleX;
    movePaddle(paddleX);
  });
  canvas.addEventListener('touchmove', (e) => {
    e.preventDefault();
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    paddleX = (e.touches[0].clientX - rect.left) * scaleX;
    movePaddle(paddleX);
  });
}

async function handleSignIn() {
  const email = document.getElementById('emailInput').value;
  const password = document.getElementById('passwordInput').value;
  if (!email || !password) {
    showStatus('Please enter email and password', 'error');
    return;
  }
  try {
    const response = await fetch('/api/signin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password })
    });
    if (!response.ok) {
      showStatus('Invalid credentials', 'error');
      return;
    }
    const data = await response.json();
    token = data.token;
    localStorage.setItem('brickfall_token', token);
    await loadProfile();
  } catch (err) {
    console.error('Sign in error:', err);
    showStatus('Sign in failed', 'error');
  }
}

async function loadProfile() {
  try {
    const response = await fetch('/api/profile', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    if (!response.ok) {
      if (response.status === 401) {
        token = null;
        localStorage.removeItem('brickfall_token');
        showSignIn();
      }
      return;
    }
    const data = await response.json();
    currentUser = data.user;
    document.getElementById('signInSection').style.display = 'none';
    document.getElementById('gameSection').style.display = 'flex';
    document.getElementById('userInfo').style.display = 'block';
    document.getElementById('signInBtn').style.display = 'none';
    document.getElementById('signOutBtn').style.display = 'block';
    document.getElementById('userEmail').textContent = currentUser.email;
    document.getElementById('userName').textContent = currentUser.name;
    await loadCurrentRun();
  } catch (err) {
    console.error('Profile load error:', err);
    showStatus('Failed to load profile', 'error');
  }
}

async function loadCurrentRun() {
  try {
    const response = await fetch('/api/run/current', {
      headers: { 'Authorization': `Bearer ${token}` }
    });
    if (response.status === 404) {
      showLevelSelect();
      return;
    }
    if (!response.ok) {
      showLevelSelect();
      return;
    }
    const data = await response.json();
    runId = data.runId;
    revision = data.revision;
    gameState = data.snapshot;
    startGameLoop();
  } catch (err) {
    console.error('Load current run error:', err);
    showLevelSelect();
  }
}

function showLevelSelect() {
  document.getElementById('levelSelect').style.display = 'block';
  const buttonsContainer = document.getElementById('levelButtons');
  buttonsContainer.innerHTML = '';
  for (let i = 1; i <= 10; i++) {
    const btn = document.createElement('button');
    btn.className = 'level-btn';
    btn.textContent = `Level ${i}`;
    if (i > currentUser.highest_level) {
      btn.classList.add('locked');
      btn.disabled = true;
    } else {
      btn.onclick = () => startNewRun(i);
    }
    buttonsContainer.appendChild(btn);
  }
}

async function startNewRun(level) {
  try {
    const response = await fetch('/api/run/start', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ level })
    });
    if (!response.ok) {
      showStatus('Failed to start run', 'error');
      return;
    }
    const data = await response.json();
    runId = data.runId;
    revision = data.revision;
    gameState = data.snapshot;
    document.getElementById('levelSelect').style.display = 'none';
    lastSaveTime = Date.now();
    startGameLoop();
  } catch (err) {
    console.error('Start run error:', err);
    showStatus('Failed to start run', 'error');
  }
}

function startGameLoop() {
  let lastFrameTime = performance.now();
  function animate(currentTime = performance.now()) {
    const deltaTime = Math.min((currentTime - lastFrameTime) / 1000, 0.016);
    lastFrameTime = currentTime;
    update(deltaTime);
    render();
    requestAnimationFrame(animate);
  }
  animate();
}

function update(deltaTime) {
  if (!gameState) return;
  let accumulator = deltaTime;
  while (accumulator >= PHYSICS_STEP && gameState.state !== 'paused' && gameState.state !== 'ready') {
    simulationStep();
    accumulator -= PHYSICS_STEP;
  }
  updateHUD();
  if (Date.now() - lastSaveTime > SAVE_INTERVAL && gameState.state === 'playing') {
    saveRun();
    lastSaveTime = Date.now();
  }
}

function simulationStep() {
  if (!gameState || gameState.state === 'paused' || gameState.state === 'ready') return;
  if (gameState.power) {
    gameState.power_seconds -= PHYSICS_STEP;
    if (gameState.power_seconds <= 0) {
      endPowerUp();
    }
  }
  updateDrops();
  updateBalls();
  const breakableBricks = gameState.bricks.filter(b => b.type !== 'solid' && b.health > 0);
  if (breakableBricks.length === 0) {
    completeLevel();
  }
  if (gameState.balls.length === 0 && gameState.lives === 0) {
    gameOver();
  }
}

function updateBalls() {
  const ballsCopy = [...gameState.balls];
  for (let i = 0; i < ballsCopy.length; i++) {
    const ball = ballsCopy[i];
    if (ball.stuck) {
      ball.x = paddleX + gameState.paddle_width / 2;
      ball.y = CANVAS_HEIGHT - 40 - BALL_RADIUS;
      continue;
    }
    const newX = ball.x + ball.vx * PHYSICS_STEP;
    const newY = ball.y + ball.vy * PHYSICS_STEP;
    let hitBrick = null;
    for (let j = 0; j < gameState.bricks.length; j++) {
      const brick = gameState.bricks[j];
      if (brick.health > 0 && checkCircleRectCollision(ball.x, ball.y, BALL_RADIUS, brick.x, brick.y, brick.width, brick.height)) {
        hitBrick = j;
        break;
      }
    }
    if (hitBrick !== null) {
      const brick = gameState.bricks[hitBrick];
      const collision = getCollisionNormal(ball.x, ball.y, BALL_RADIUS, brick.x, brick.y, brick.width, brick.height);
      ball.x = collision.point.x;
      ball.y = collision.point.y;
      const speed = Math.sqrt(ball.vx ** 2 + ball.vy ** 2);
      const reflected = reflectVelocity(ball.vx, ball.vy, collision.normal.x, collision.normal.y);
      ball.vx = reflected.x;
      ball.vy = reflected.y;
      const newSpeed = Math.sqrt(ball.vx ** 2 + ball.vy ** 2);
      if (newSpeed < MIN_VELOCITY && newSpeed > 0) {
        const factor = MIN_VELOCITY / newSpeed;
        ball.vx *= factor;
        ball.vy *= factor;
      }
      if (brick.type !== 'solid') {
        if (brick.type === 'normal') {
          gameState.score += 100 * gameState.combo;
          brick.health = 0;
        } else if (brick.type === 'strong') {
          if (!brick.damaged) {
            gameState.score += 75 * gameState.combo;
            brick.damaged = true;
          } else {
            gameState.score += 250 * gameState.combo;
            brick.health = 0;
          }
        }
        gameState.combo = Math.min(gameState.combo + 1, 5);
        if (gameState.score >= gameState.next_extra_life) {
          gameState.lives++;
          gameState.next_extra_life += constants.extra_life_step;
        }
      }
    } else {
      if (checkCircleRectCollision(ball.x, ball.y, BALL_RADIUS, paddleX, CANVAS_HEIGHT - 40, gameState.paddle_width, PADDLE_HEIGHT)) {
        const collision = getCollisionNormal(ball.x, ball.y, BALL_RADIUS, paddleX, CANVAS_HEIGHT - 40, gameState.paddle_width, PADDLE_HEIGHT);
        ball.x = collision.point.x;
        ball.y = collision.point.y;
        const paddleCenter = paddleX + gameState.paddle_width / 2;
        const hitOffset = (ball.x - paddleCenter) / (gameState.paddle_width / 2);
        const steerAngle = Math.max(-Math.PI / 6, Math.min(Math.PI / 6, hitOffset * Math.PI / 6));
        const speed = Math.sqrt(ball.vx ** 2 + ball.vy ** 2);
        ball.vx = Math.sin(steerAngle) * speed;
        ball.vy = -Math.cos(steerAngle) * speed;
        gameState.combo = 1;
        if (ball.stuck) {
          ball.stuck = false;
        }
      } else {
        ball.x = newX;
        ball.y = newY;
      }
    }
    if (ball.y > CANVAS_HEIGHT) {
      gameState.balls = gameState.balls.filter(b => b.id !== ball.id);
      if (gameState.balls.length === 0) {
        loseLife();
      }
    }
  }
}

function updateDrops() {
  for (let i = gameState.drops.length - 1; i >= 0; i--) {
    const drop = gameState.drops[i];
    drop.y += drop.vy * PHYSICS_STEP;
    if (drop.y + 8 > CANVAS_HEIGHT - 40 && drop.y - 8 < CANVAS_HEIGHT - 40 + PADDLE_HEIGHT && drop.x + 8 > paddleX && drop.x - 8 < paddleX + gameState.paddle_width) {
      collectPowerUp(drop.type);
      gameState.drops.splice(i, 1);
    } else if (drop.y > CANVAS_HEIGHT) {
      gameState.drops.splice(i, 1);
    }
  }
}

function collectPowerUp(type) {
  if (gameState.power === type) {
    gameState.power_seconds = constants.powerup_duration_seconds;
  } else {
    if (gameState.power) {
      endPowerUp();
    }
    gameState.power = type;
    gameState.power_seconds = constants.powerup_duration_seconds;
    if (type === 'wide') {
      gameState.paddle_width = 118 * 1.5;
    } else if (type === 'slow') {
      const speed = Math.sqrt(gameState.balls[0].vx ** 2 + gameState.balls[0].vy ** 2);
      const newSpeed = speed * 0.7;
      const factor = newSpeed / speed;
      gameState.balls.forEach(b => {
        b.vx *= factor;
        b.vy *= factor;
      });
    } else if (type === 'multiball') {
      if (gameState.balls.length === 1) {
        const primary = gameState.balls[0];
        gameState.balls.push({
          id: 'secondary',
          x: primary.x,
          y: primary.y,
          vx: primary.vx,
          vy: primary.vy,
          stuck: false
        });
      }
    } else if (type === 'sticky') {
      if (gameState.balls.length > 0) {
        gameState.balls[0].stuck = true;
      }
    }
  }
}

function endPowerUp() {
  if (gameState.power === 'wide') {
    gameState.paddle_width = 118;
  } else if (gameState.power === 'slow') {
    gameState.balls.forEach(b => {
      const speed = Math.sqrt(b.vx ** 2 + b.vy ** 2);
      if (speed > 0) {
        const factor = Math.min(constants.speed_cap, speed) / speed;
        b.vx *= factor;
        b.vy *= factor;
      }
    });
  } else if (gameState.power === 'multiball') {
    gameState.balls = gameState.balls.filter(b => b.id === 'primary');
  } else if (gameState.power === 'sticky') {
    if (gameState.balls.length > 0 && gameState.balls[0].stuck) {
      gameState.balls[0].stuck = false;
    }
  }
  gameState.power = null;
  gameState.power_seconds = 0;
}

function loseLife() {
  gameState.lives--;
  gameState.drops = [];
  endPowerUp();
  if (gameState.lives > 0) {
    gameState.state = 'life-lost';
  } else {
    gameOver();
  }
}

function completeLevel() {
  gameState.score += 1000 * gameState.level;
  gameState.state = 'level-complete';
}

function gameOver() {
  gameState.state = 'game-over';
}

function render() {
  if (!gameState) return;
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
  gameState.bricks.forEach(brick => {
    if (brick.health > 0) {
      if (brick.type === 'solid') {
        ctx.fillStyle = '#333';
      } else if (brick.type === 'strong') {
        ctx.fillStyle = brick.damaged ? '#ff6b6b' : '#ff8c42';
      } else {
